-- Synthetic metadata only. Storage API deletion is covered separately by server tests.
begin;
insert into auth.users(id) values('55000000-0000-4000-8000-000000000001'),('55000000-0000-4000-8000-000000000002'),('55000000-0000-4000-8000-000000000003');
set local role authenticated;
select set_config('request.jwt.claim.sub','55000000-0000-4000-8000-000000000001',true);
do $$declare org uuid;co uuid;other uuid;p uuid;op uuid;a uuid;b uuid;doc uuid:=gen_random_uuid();other_doc uuid:=gen_random_uuid();path text;other_path text;s jsonb;job uuid;newco uuid;ex uuid;before_count int;deleted_count int;begin
 org:=(public.create_organization('Estudio sintético para eliminación')).id;
 insert into public.companies(organization_id,legal_name,cuit) values(org,'Empresa a quitar','30719990017') returning id into co;
 insert into public.companies(organization_id,legal_name,cuit) values(org,'Empresa conservada','30719990025') returning id into other;
 p:=(public.ensure_period(co,'2026-11-01')).id;op:=(public.ensure_period(other,'2026-11-01')).id;
 insert into public.accounts(organization_id,company_id,code,name,kind) values(org,co,'1','Agrupadora','asset') returning id into a;
 insert into public.accounts(organization_id,company_id,code,name,kind,parent_code) values(org,co,'1.1','Banco ficticio','asset','1') returning id into b;
 if to_regclass('public.accounting_account_profiles') is not null then perform public.save_accounting_profile(b,'Disponibilidades','Bancos','debit',true,'101');end if;
 path:=org::text||'/'||co::text||'/'||p::text||'/'||doc::text;other_path:=org::text||'/'||other::text||'/'||op::text||'/'||other_doc::text;
 insert into storage.objects(bucket_id,name,owner_id,metadata) values('accounting-documents',path,auth.uid()::text,'{"size":4,"mimetype":"text/csv"}'),('accounting-documents',other_path,auth.uid()::text,'{"size":4,"mimetype":"text/csv"}');
 insert into public.documents(id,organization_id,company_id,period_id,name,category,storage_path,mime_type,size_bytes) values(doc,org,co,p,'respaldo-ficticio.csv','Respaldos',path,'text/csv',4),(other_doc,org,other,op,'otro-ficticio.csv','Respaldos',other_path,'text/csv',4);
 perform public.confirm_import(p,doc,'purchase',repeat('a',64),jsonb_build_array(jsonb_build_object('date','2026-11-01','receipt_type','Factura sintética','point_of_sale',1,'receipt_number',1,'counterparty_cuit','30719990025','counterparty_name','Proveedor ficticio','currency','ARS','exchange_rate','1','taxable','10.00','untaxed','0.00','exempt','0.00','vat','0.00','other_taxes','0.00','total','10.00','vat_breakdown','{}'::jsonb)));
 update public.vouchers set account_id=b where company_id=co;
 update public.close_tasks set document_id=doc where company_id=co;
 s:=public.preview_company_deletion(co);
 if (s->'counts'->>'vouchers')::int<>1 or (s->'counts'->>'documents')::int<>1 then raise exception 'Vista previa incorrecta';end if;
 perform public.set_organization_member(org,'55000000-0000-4000-8000-000000000002','editor');
 perform public.set_organization_member(org,'55000000-0000-4000-8000-000000000003','viewer');
 perform set_config('request.jwt.claim.sub','55000000-0000-4000-8000-000000000002',true);
 begin perform public.preview_company_deletion(co);raise exception 'Editor puede revisar eliminación';exception when insufficient_privilege then null;end;
 begin perform public.delete_workspace_company(co,'30719990017',s->>'signature');raise exception 'Editor puede eliminar';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','55000000-0000-4000-8000-000000000003',true);
 begin perform public.delete_workspace_company(co,'30719990017',s->>'signature');raise exception 'Viewer puede eliminar';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','55000000-0000-4000-8000-000000000001',true);
 begin perform public.delete_workspace_company(co,'30719990025',s->>'signature');raise exception 'CUIT incorrecto aceptado';exception when invalid_parameter_value then null;end;
 update public.vouchers set notes='Datos revisados' where company_id=co;
 begin perform public.delete_workspace_company(co,'30719990017',s->>'signature');raise exception 'Confirmación desactualizada admitida';exception when serialization_failure then null;end;
 if not exists(select 1 from public.companies where id=co) or not exists(select 1 from public.documents where id=doc) then raise exception 'Hubo eliminación parcial';end if;
 s:=public.preview_company_deletion(co);job:=public.delete_workspace_company(co,'30719990017',s->>'signature');
 if public.delete_workspace_company(co,'30719990017',s->>'signature')<>job then raise exception 'Reintento no idempotente';end if;
 if exists(select 1 from public.companies where id=co) or exists(select 1 from public.accounts where company_id=co) or exists(select 1 from public.vouchers where company_id=co) or exists(select 1 from public.documents where company_id=co) or exists(select 1 from public.periods where company_id=co) then raise exception 'Quedaron cargas relacionales';end if;
 if not exists(select 1 from public.companies where id=other) or not exists(select 1 from public.documents where id=other_doc) then raise exception 'Se eliminó otra empresa';end if;
 if not exists(select 1 from public.audit_events where entity='company_deletion' and entity_id=job) then raise exception 'Falta comprobante de eliminación';end if;
 if to_regclass('public.accounting_change_history') is not null then
  if not exists(select 1 from public.accounting_change_history where company_id=co) then raise exception 'Se perdió el historial inmutable';end if;
 end if;
 begin perform public.complete_company_deletion(job);raise exception 'Se anunció limpieza sin retirar archivos';exception when object_not_in_prerequisite_state then null;end;
 if not accounting_private.can_cleanup_deleted_company_object('accounting-documents',path) or accounting_private.can_cleanup_deleted_company_object('accounting-documents',other_path) then raise exception 'Permisos de archivo mal acotados';end if;
 delete from storage.objects where bucket_id='accounting-documents' and name=other_path;get diagnostics deleted_count=row_count;if deleted_count<>0 then raise exception 'Se pudo borrar archivo de otra empresa';end if;
 perform set_config('request.jwt.claim.sub','55000000-0000-4000-8000-000000000002',true);
 if exists(select 1 from public.company_deletions where id=job) then raise exception 'Editor puede consultar la limpieza';end if;
 delete from storage.objects where bucket_id='accounting-documents' and name=path;get diagnostics deleted_count=row_count;if deleted_count<>0 then raise exception 'Editor pudo borrar archivo del trabajo';end if;
 perform set_config('request.jwt.claim.sub','55000000-0000-4000-8000-000000000001',true);
 delete from storage.objects where bucket_id='accounting-documents' and name=path;get diagnostics deleted_count=row_count;if deleted_count<>1 then raise exception 'No se pudo limpiar archivo autorizado';end if;
 perform public.complete_company_deletion(job);
 if (select status from public.company_deletions where id=job)<>'completed' then raise exception 'No se completó limpieza';end if;
 begin insert into storage.objects(bucket_id,name,owner_id,metadata) values('accounting-documents',path,auth.uid()::text,'{"size":4,"mimetype":"text/csv"}');raise exception 'Se pudo subir a empresa eliminada';exception when object_not_in_prerequisite_state then null;end;
 insert into public.companies(organization_id,legal_name,cuit) values(org,'Empresa nueva con mismo CUIT','30719990017') returning id into newco;
 if newco=co then raise exception 'No se creó identidad nueva';end if;
 if to_regclass('public.accounting_journal_entries') is not null then
  p:=(public.ensure_period(newco,'2026-11-01')).id;
  insert into public.accounts(organization_id,company_id,code,name,kind) values(org,newco,'1','Banco nuevo','asset') returning id into a;
  insert into public.accounts(organization_id,company_id,code,name,kind) values(org,newco,'3','Capital nuevo','equity') returning id into b;
  ex:=public.create_accounting_exercise(newco,'Ejercicio ficticio','2026-01-01','2026-12-31');
  perform public.post_accounting_entry(p,ex,'2026-11-01','Asiento protegido','protected',jsonb_build_array(jsonb_build_object('account_id',a,'debit','10.00','credit','0.00'),jsonb_build_object('account_id',b,'debit','0.00','credit','10.00')));
  s:=public.preview_company_deletion(newco);
  if jsonb_array_length(s->'blocked')=0 then raise exception 'No se detectó Diario confirmado';end if;
  begin perform public.delete_workspace_company(newco,'30719990017',s->>'signature');raise exception 'Eliminó asientos confirmados';exception when object_not_in_prerequisite_state then null;end;
 end if;
 raise notice 'ELIMINACIÓN OK: propietaria/CUIT/huella, eliminación real, otras empresas intactas, historial conservado, Storage pendiente/reintento, CUIT reutilizable y asientos confirmados protegidos';
end $$;
rollback;
